"use client";

import { loadFont } from "@remotion/google-fonts/Figtree";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import {
  AbsoluteFill,
  Easing,
  Img,
  interpolate,
  spring,
  staticFile,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_LINES,
  DEFAULT_ROWS,
  DEFAULT_TITLE,
  type TiltSettleListElementId,
  tiltSettleListTimeline,
} from "./timeline";

const figtree = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});
const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"] });

export interface ListRow {
  title: string;
  meta: string;
  src?: string;
}

export interface TiltSettleListProps {
  title?: string;
  accentWord?: number;
  heroTitle?: string;
  heroMeta?: string;
  heroSrc?: string;
  lines?: string[];
  rows?: ListRow[];
  theme?: "dark" | "light";
  accent?: string;
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Figtree by default. */
  fontFamily?: string;
  /** Frames between title words as the heading builds. */
  stagger?: number;
  /** Frames each checklist line stays highlighted before the next one. */
  step?: number;
  /** Size of the foreground, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /**
   * Moves, trims or stretches the title words, the card, the checklist and
   * its highlight steps, and the rows, by the ids in `./timeline`. Frames on
   * the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<TiltSettleListElementId>;
}

const THEMES = {
  dark: {
    ink: "#eefaf5",
    sub: "rgba(238,250,245,0.56)",
    faint: "rgba(238,250,245,0.34)",
    accent: "#6ff0c0",
    ground: "polar" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    card: "linear-gradient(180deg, rgba(30,36,38,0.94) 0%, rgba(15,19,21,0.94) 100%)",
    cardLine: "rgba(255,255,255,0.07)",
    cardTop: "rgba(255,255,255,0.08)",
    track: "rgba(255,255,255,0.14)",
    divider: "rgba(255,255,255,0.1)",
    play: "#f4fbf8",
    playIcon: "#0b1512",
    shadowRgb: "0,6,6",
    shadowK: 1,
  },
  light: {
    ink: "#13151c",
    sub: "rgba(19,21,28,0.56)",
    faint: "rgba(19,21,28,0.3)",
    accent: "#3552ff",
    ground: "glasswork" as GshPresetId | undefined,
    groundParams: { seed: 3 } as Partial<GradientParams> | undefined,
    card: "linear-gradient(180deg, #ffffff 0%, #f7f8fb 100%)",
    cardLine: "rgba(19,21,40,0.07)",
    cardTop: "rgba(255,255,255,1)",
    track: "rgba(19,21,40,0.1)",
    divider: "rgba(19,21,40,0.08)",
    play: "#13151c",
    playIcon: "#ffffff",
    shadowRgb: "30,36,80",
    shadowK: 0.45,
  },
};

const VISIBLE = 6;

const EASE_ENTER = Easing.bezier(0.32, 0.72, 0, 1);
const EASE_MOVE = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const SPRING_SWING = { mass: 1, damping: 17, stiffness: 110 };
const SPRING_HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const SPRING_CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const SPRING_CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

function Reveal({
  frame,
  at,
  children,
}: {
  frame: number;
  at: number;
  children: React.ReactNode;
}) {
  const p = interpolate(frame, [at, at + 12], [0, 1], {
    ...CLAMP,
    easing: EASE_ENTER,
  });
  return (
    <div
      style={{
        overflow: "hidden",
        padding: "0.04em 0.04em 0.16em",
        margin: "-0.04em -0.04em -0.16em",
      }}
    >
      <div
        style={{
          transform: `translateY(${(1 - p) * 140}%)`,
          filter: `blur(${(1 - p) * 4}px)`,
        }}
      >
        {children}
      </div>
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function TiltSettleList(props: TiltSettleListProps) {
  const {
    title = DEFAULT_TITLE,
    accentWord = 1,
    heroTitle = "Zoom Blur",
    heroMeta = "Transition · 2.4k renders",
    heroSrc,
    lines = DEFAULT_LINES,
    rows,
    theme = "dark",
    accent,
    ink,
    background,
    fontFamily = figtree.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    ground,
    groundParams,
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    tiltSettleListTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const card = tl.get("card");
  const camera = tl.get("camera");
  const hero = tl.get("hero");
  const reveal = tl.get("lines");
  const steps = lines.map((_, i) => tl.get(`line:${i}`));
  const t = THEMES[theme];
  const light = theme === "light";
  const fg = ink ?? t.ink;
  const acc = accent ?? t.accent;
  const preset = ground ?? (groundParams ? undefined : t.ground);
  const gParams = groundParams ?? (ground ? undefined : t.groundParams);
  const portrait = H > W;
  const S = Math.min(W, H);
  const k = t.shadowK;
  const cover = heroSrc ?? staticFile("templates/launch-anything/horizon.jpg");
  const list = (
    rows ?? DEFAULT_ROWS.map((r) => ({ ...r, src: staticFile(r.src ?? "") }))
  ).slice(0, 4);

  const titleSize = portrait ? W * 0.085 : W * 0.046;
  const titleY = portrait ? H * 0.09 : H * 0.115;

  const cardW = portrait ? W * 0.88 : W * 0.55;
  const cardH = portrait ? H * 0.42 : H * 0.66;
  const cardX = portrait ? W * 0.06 : W * 0.035;
  const cardY = portrait ? H * 0.16 : H * 0.235;
  const pad = S * 0.04;
  const coverS = portrait ? cardW * 0.42 : cardH * 0.56;
  const lineSize = portrait ? W * 0.036 : S * 0.04;
  const lineH = lineSize * 1.42;

  const swing = spring({
    frame: frame - card.start,
    fps,
    config: SPRING_SWING,
  });
  const swingPrev = spring({
    frame: frame - card.start - 1,
    fps,
    config: SPRING_SWING,
  });
  const fly = 1 - swing;
  const mb = Math.min(10, Math.abs(swing - swingPrev) * H * 0.5 * 0.1);
  const settleRY = portrait ? 0 : 12;
  const settleRX = portrait ? 6 : 3;
  const rz = -16 * fly;
  const rx = settleRX + 40 * fly;
  const ry = settleRY - 18 * fly;
  const ty = H * 0.5 * fly;
  const tx = -W * 0.06 * fly;
  const sc = 1 + 0.12 * fly;

  const pushAt = (f: number) =>
    interpolate(f, [camera.start, camera.end], [1, 1.04], {
      ...CLAMP,
      easing: EASE_CAMERA,
    });
  const push = pushAt(frame);
  // The camera's ease is very flat at both ends, so "moving" is the scale step
  // weighed at the frame's edge, against the neighbouring frames.
  const pushMoving =
    Math.abs(pushAt(frame + speed) - push) * W * 0.5 > 1e-3 ||
    Math.abs(push - pushAt(frame - speed)) * W * 0.5 > 1e-3;
  // The highlight has moved past every line whose step has started.
  let stepped = 0;
  while (stepped < lines.length - 1 && frame >= steps[stepped + 1].start) {
    stepped++;
  }
  const scrollP = spring({
    frame: frame - (steps[stepped]?.start ?? 0),
    fps,
    config: SPRING_HEAVY,
  });
  const maxScroll = Math.max(0, lines.length - VISIBLE);
  const scrollTo = Math.min(maxScroll, Math.max(0, stepped - 1));
  const scrollFrom = Math.min(maxScroll, Math.max(0, stepped - 2));
  const scrollIdx = scrollFrom + (scrollTo - scrollFrom) * scrollP;
  const progress = interpolate(
    frame,
    [camera.start, camera.end],
    [0.08, 0.72],
    {
      ...CLAMP,
      easing: EASE_MOVE,
    },
  );

  const listX = portrait ? W * 0.08 : W * 0.635;
  const listW = portrait ? W * 0.84 : W * 0.32;
  const listY = portrait ? H * 0.63 : H * 0.33;
  const rowH = portrait ? H * 0.085 : H * 0.15;
  const thumb = portrait ? W * 0.13 : S * 0.085;
  const rowTitle = portrait ? W * 0.045 : S * 0.033;
  const rowMeta = portrait ? W * 0.032 : S * 0.024;
  const rankW = portrait ? W * 0.07 : S * 0.05;
  const playS = portrait ? W * 0.085 : S * 0.056;

  const titleWords = title.split(" ");
  const fmt = (s: number) => `0:${String(Math.floor(s)).padStart(2, "0")}`;

  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      {background === undefined ? (
        <GshGround
          preset={preset}
          params={gParams}
          timeOffset={light ? 2 : 4}
          timeScale={0.7}
        />
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden>
        <filter id="tsl-mb" x="-20%" y="-30%" width="140%" height="160%">
          <feGaussianBlur stdDeviation={`${mb * 0.3} ${mb}`} />
        </filter>
      </svg>
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{ transform: `scale(${push})${glide(pushMoving)}` }}
        >
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: titleY - titleSize * 0.55,
              display: "flex",
              justifyContent: "center",
              columnGap: "0.24em",
              fontFamily,
              fontWeight: 300,
              fontSize: titleSize,
              letterSpacing: "-0.04em",
              lineHeight: 1.1,
              color: fg,
            }}
          >
            {titleWords.map((word, i) => {
              const w = tl.get(`word:${i}`);
              const p = interpolate(frame, [w.start, w.end], [0, 1], {
                ...CLAMP,
                easing: EASE_ENTER,
              });
              return (
                <span
                  key={`${word}-${i}`}
                  style={{
                    display: "inline-block",
                    overflow: "hidden",
                    padding: "0.04em 0.04em 0.16em",
                    margin: "-0.04em -0.04em -0.16em",
                  }}
                >
                  <span
                    style={{
                      display: "inline-block",
                      transform: `translateY(${(1 - p) * 140}%)`,
                      filter: `blur(${(1 - p) * 6}px)`,
                      color: i === accentWord ? acc : undefined,
                      fontWeight: i === accentWord ? 400 : 300,
                    }}
                  >
                    {word}
                  </span>
                </span>
              );
            })}
          </div>
          <AbsoluteFill style={{ perspective: portrait ? 2000 : 1300 }}>
            <div
              style={{
                position: "absolute",
                left: cardX,
                top: cardY,
                width: cardW,
                height: cardH,
                borderRadius: S * 0.034,
                backgroundImage: t.card,
                boxShadow: `inset 0 1px 0 ${t.cardTop}, inset 0 0 0 1px ${t.cardLine}, 0 2px 6px rgba(${t.shadowRgb},${0.3 * k}), 0 ${S * 0.04}px ${S * 0.1}px rgba(${t.shadowRgb},${0.4 * k}), 0 ${S * 0.1}px ${S * 0.24}px rgba(${t.shadowRgb},${0.4 * k})`,
                transformOrigin: "30% 100%",
                transform: `translate(${tx}px, ${ty}px) rotateX(${rx}deg) rotateY(${ry}deg) rotateZ(${rz}deg) scale(${sc})`,
                filter: mb > 0.4 ? "url(#tsl-mb)" : undefined,
                overflow: "hidden",
                fontFamily,
                color: fg,
              }}
            >
              <div
                style={{
                  position: "absolute",
                  left: pad,
                  top: pad,
                  width: coverS,
                  height: coverS,
                  borderRadius: S * 0.016,
                  overflow: "hidden",
                  boxShadow: `0 ${S * 0.012}px ${S * 0.03}px rgba(${t.shadowRgb},${0.4 * k})`,
                }}
              >
                <Img
                  src={cover}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    display: "block",
                  }}
                />
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    borderRadius: "inherit",
                    boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.12)",
                  }}
                />
              </div>
              <div
                style={{
                  position: "absolute",
                  left: pad,
                  top: pad + coverS + pad * 0.6,
                  width: coverS,
                }}
              >
                <Reveal frame={frame} at={hero.start}>
                  <div
                    style={{
                      fontSize: lineSize * 1.12,
                      fontWeight: 400,
                      letterSpacing: "-0.025em",
                      lineHeight: 1.15,
                    }}
                  >
                    {heroTitle}
                  </div>
                </Reveal>
                <Reveal frame={frame} at={hero.start + hero.beat("meta")}>
                  <div
                    style={{
                      fontSize: lineSize * 0.74,
                      fontWeight: 300,
                      color: t.sub,
                      marginTop: lineSize * 0.2,
                      whiteSpace: "nowrap",
                    }}
                  >
                    {heroMeta}
                  </div>
                </Reveal>
              </div>
              <div
                style={{
                  position: "absolute",
                  left: pad * 2 + coverS,
                  right: pad,
                  top: pad,
                  height: lineH * VISIBLE,
                  overflow: "hidden",
                  maskImage:
                    "linear-gradient(180deg, transparent 0%, #000 16%, #000 100%)",
                }}
              >
                <div
                  style={{
                    transform: `translateY(${-scrollIdx * lineH}px)`,
                  }}
                >
                  {lines.map((line, i) => {
                    const e = steps[i];
                    const on = interpolate(
                      frame,
                      [
                        e.start,
                        e.start + e.beat("fade"),
                        e.end,
                        e.end + e.beat("fade"),
                      ],
                      [0, 1, 1, i === lines.length - 1 ? 1 : 0],
                      { ...CLAMP, easing: EASE_MOVE },
                    );
                    return (
                      <div
                        key={line}
                        style={{
                          height: lineH,
                          display: "flex",
                          alignItems: "center",
                        }}
                      >
                        <Reveal
                          frame={frame}
                          at={reveal.start + i * reveal.beat("stagger")}
                        >
                          <div
                            style={{
                              fontSize: lineSize,
                              fontWeight: 300,
                              letterSpacing: "-0.02em",
                              whiteSpace: "nowrap",
                              color: fg,
                              opacity: 0.34 + 0.66 * on,
                            }}
                          >
                            {line}
                          </div>
                        </Reveal>
                      </div>
                    );
                  })}
                </div>
              </div>
              <div
                style={{
                  position: "absolute",
                  left: pad * 2 + coverS,
                  right: pad,
                  bottom: pad,
                  fontFamily: mono.fontFamily,
                  fontSize: Math.max(S * 0.022, lineSize * 0.6),
                  color: t.sub,
                }}
              >
                <div
                  style={{
                    height: Math.max(3, S * 0.005),
                    borderRadius: 99,
                    backgroundColor: t.track,
                    position: "relative",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      left: 0,
                      top: 0,
                      bottom: 0,
                      width: `${progress * 100}%`,
                      borderRadius: 99,
                      backgroundColor: fg,
                    }}
                  />
                  {/* The knob rides the track by a transform, not `left`:
                      layout rounds a box to whole pixels, so a knob eased by
                      `left` steps along pixel by pixel. The carrier spans the
                      track, so its own-width percent is the track's. */}
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      transform: `translateX(${progress * 100}%)`,
                    }}
                  >
                    <div
                      style={{
                        position: "absolute",
                        left: 0,
                        top: "50%",
                        width: S * 0.016,
                        height: S * 0.016,
                        marginLeft: -S * 0.008,
                        marginTop: -S * 0.008,
                        borderRadius: 99,
                        backgroundColor: fg,
                      }}
                    />
                  </div>
                </div>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    marginTop: S * 0.014,
                  }}
                >
                  <span>{fmt(progress * 6)}</span>
                  <span>-{fmt(6 - progress * 6)}</span>
                </div>
              </div>
            </div>
          </AbsoluteFill>
          <div
            style={{
              position: "absolute",
              left: listX,
              top: listY,
              width: listW,
              fontFamily,
              color: fg,
            }}
          >
            {list.map((row, i) => {
              const e = tl.get(`row:${i}`);
              const at = e.start;
              const slide = spring({
                frame: frame - at,
                fps,
                config: SPRING_CARD,
              });
              const thumbP = spring({
                frame: frame - at - e.beat("thumb"),
                fps,
                config: SPRING_CHIP,
              });
              const playP = spring({
                frame: frame - at - e.beat("play"),
                fps,
                config: SPRING_CHIP,
              });
              const divider = interpolate(
                frame,
                [at + e.beat("divider"), at + e.beat("dividerEnd")],
                [0, 1],
                {
                  ...CLAMP,
                  easing: EASE_MOVE,
                },
              );
              return (
                <div
                  key={row.title}
                  style={{
                    position: "relative",
                    height: rowH,
                    display: "flex",
                    alignItems: "center",
                    gap: S * 0.022,
                    transform: `translateX(${(1 - slide) * S * 0.16}px)`,
                    opacity: Math.min(1, slide * 2.5),
                  }}
                >
                  <div
                    style={{
                      width: rankW,
                      flexShrink: 0,
                      fontFamily: mono.fontFamily,
                      fontSize: rowTitle,
                      color: t.sub,
                      textAlign: "right",
                    }}
                  >
                    {i + 2}
                  </div>
                  <div
                    style={{
                      width: thumb,
                      height: thumb,
                      flexShrink: 0,
                      borderRadius: thumb * 0.16,
                      overflow: "hidden",
                      transform: `scale(${thumbP})`,
                      boxShadow: `0 ${thumb * 0.08}px ${thumb * 0.2}px rgba(${t.shadowRgb},${0.4 * k}), inset 0 0 0 1px rgba(255,255,255,0.1)`,
                    }}
                  >
                    <Img
                      src={row.src ?? cover}
                      style={{
                        width: "100%",
                        height: "100%",
                        objectFit: "cover",
                        display: "block",
                      }}
                    />
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <Reveal frame={frame} at={at + e.beat("title")}>
                      <div
                        style={{
                          fontSize: rowTitle,
                          fontWeight: 400,
                          letterSpacing: "-0.02em",
                          lineHeight: 1.15,
                          whiteSpace: "nowrap",
                        }}
                      >
                        {row.title}
                      </div>
                    </Reveal>
                    <Reveal frame={frame} at={at + e.beat("meta")}>
                      <div
                        style={{
                          fontSize: rowMeta,
                          fontWeight: 300,
                          color: t.sub,
                          marginTop: rowMeta * 0.2,
                          whiteSpace: "nowrap",
                        }}
                      >
                        {row.meta}
                      </div>
                    </Reveal>
                  </div>
                  <div
                    style={{
                      width: playS,
                      height: playS,
                      flexShrink: 0,
                      borderRadius: 99,
                      backgroundColor: t.play,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      transform: `scale(${playP})`,
                      boxShadow: `0 ${playS * 0.1}px ${playS * 0.3}px rgba(${t.shadowRgb},${0.35 * k})`,
                    }}
                  >
                    <svg
                      width={playS * 0.4}
                      height={playS * 0.4}
                      viewBox="0 0 24 24"
                      aria-hidden
                    >
                      <path d="M8 5.5v13l10.5-6.5z" fill={t.playIcon} />
                    </svg>
                  </div>
                  {i < list.length - 1 ? (
                    <div
                      style={{
                        position: "absolute",
                        left: rankW + S * 0.022,
                        right: 0,
                        bottom: 0,
                        height: 1,
                        backgroundColor: t.divider,
                        transformOrigin: "0 50%",
                        transform: `scaleX(${divider})`,
                      }}
                    />
                  ) : null}
                </div>
              );
            })}
          </div>
        </AbsoluteFill>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

export default TiltSettleList;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The heading building word by word while the player card swings up and
// settles, the hero copy and the checklist revealing, the highlight stepping
// down the checklist, and the ranked rows sliding in beside the card, all
// under a slow camera push. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. The ids are public: a saved `timing` prop refers to
// them.

export type TiltSettleListElementId =
  | `word:${number}`
  | "card"
  | "camera"
  | "hero"
  | "lines"
  | `line:${number}`
  | `row:${number}`;

export interface TiltSettleListTimingProps {
  title?: string;
  lines?: readonly string[];
  rows?: readonly { title: string }[];
  stagger?: number;
  step?: number;
}

export const DEFAULT_TITLE = "Your top scenes";
export const DEFAULT_LINES = [
  "Open on the product",
  "Type the headline",
  "Zoom blur to the demo",
  "Show the editor",
  "Cut to pricing",
  "Fan the formats",
  "Land the logo",
  "Fade to the URL",
];
export const DEFAULT_ROWS = [
  {
    title: "Text Reveal",
    meta: "1.2k renders",
    src: "templates/brand-guidelines/ceramics.jpg",
  },
  {
    title: "Logo Orbit",
    meta: "980 renders",
    src: "templates/launch-anything/earth.jpg",
  },
  { title: "Card Fan", meta: "740 renders", src: "reel/reel-2.jpg" },
];

const TITLE = -6;
const CARD = -2;
const LINES = 10;
const ROWS = 30;
const STEP_AT = 24;
const END = 126;
const STEP = 14;
const ROW_TIMES = [0, 6, 11];

// `word:<i>` rises title word i in over its length; the words form a chain.
// `card` swings the player card up on a spring from its start. `camera`
// pushes in and runs the scrubber over its length. `hero` reveals the hero
// title, its meta `meta` later. `lines` reveals the checklist, each line
// `stagger` after the one before. `line:<i>` highlights checklist line i,
// fading in over `fade`, and hands over to the next at its end, where the
// list scrolls on; a chain. `row:<i>` slides ranked row i in on a spring,
// popping its thumb at `thumb` and play button at `play`, revealing its
// title at `title` and meta at `meta`, and drawing its divider from
// `divider` to `dividerEnd`.
export const tiltSettleListTimeline = defineTimeline<
  TiltSettleListElementId,
  TiltSettleListTimingProps
>(
  ({
    title = DEFAULT_TITLE,
    lines = DEFAULT_LINES,
    rows,
    stagger = 3,
    step = STEP,
  }) => {
    const elements: TimelineElement<TiltSettleListElementId>[] = [];
    title.split(" ").forEach((word, i) => {
      elements.push({
        id: `word:${i}`,
        lane: "Title",
        label: word,
        start: TITLE + i * stagger,
        length: 12,
        follows: i > 0 ? `word:${i - 1}` : undefined,
      });
    });
    elements.push(
      { id: "card", lane: "Card", label: "Card", start: CARD, length: 32 },
      { id: "camera", lane: "Camera", label: "Push", start: 0, length: END },
      {
        id: "hero",
        lane: "Card",
        label: "Hero",
        start: LINES - 2,
        length: 14,
        beats: { meta: 2 },
      },
      {
        id: "lines",
        lane: "Card",
        label: "Checklist",
        start: LINES,
        length: 12 + Math.max(0, lines.length - 1) * 2,
        beats: { stagger: 2 },
      },
    );
    lines.forEach((line, i) => {
      elements.push({
        id: `line:${i}`,
        lane: "Highlight",
        label: line,
        start: STEP_AT + (i - 1) * step,
        length: step,
        follows: i > 0 ? `line:${i - 1}` : undefined,
        beats: { fade: 6 },
      });
    });
    (rows ?? DEFAULT_ROWS).slice(0, 4).forEach((row, i) => {
      elements.push({
        id: `row:${i}`,
        lane: "Rows",
        label: row.title,
        start: ROWS + (ROW_TIMES[i] ?? i * 5),
        length: 18,
        follows: i > 0 ? `row:${i - 1}` : undefined,
        beats: {
          thumb: 2,
          play: 6,
          title: 3,
          meta: 5,
          divider: 4,
          dividerEnd: 18,
        },
      });
    });
    return elements
      .map((e, k) => ({ e, k }))
      .sort((a, b) => a.e.start - b.e.start || a.k - b.k)
      .map(({ e }) => e);
  },
);
